// Captured profiles made on Chrome up to 117 carry a Windows WebGL renderer with no PCI device id:
//   ANGLE (NVIDIA, NVIDIA GeForce RTX 4070 Ti Direct3D11 vs_5_0 ps_5_0, D3D11)
// Chrome 118 and later always print "(0x%08X)" before "Direct3D11", so an engine on 156 showing the old
// shape shows a string it cannot produce (the /audit row webgl-renderer-angle-format flags it). These add
// the id real captures of the same card print. Same rules as the Python and .NET SDKs and the Profile
// Manager; the table is generated by sdk/scripts/gen_angle_device_ids.py.

import { BY_ARCH, BY_NAME } from "./angledeviceids.generated.js";

const NO_ID = /^ANGLE \(([^,]+), (.+?) (Direct3D11(?:on12)? vs_\d_\d ps_\d_\d, D3D11\))$/;

/** The renderer with the device id ANGLE prints for that card; unchanged when it has one already, is
 * not a Direct3D 11 renderer, or the card is not in the table. `arch` is the capture's WebGPU
 * architecture: it picks an id of the same chip generation for a generic name. */
export function withAngleDeviceId(renderer: string, arch = ""): string {
  if (renderer.includes("(0x")) return renderer;
  const m = NO_ID.exec(renderer);
  if (!m) return renderer;
  const [, vendor, name, tail] = m;
  const id = BY_ARCH[`${vendor}|${name}|${arch}`] ?? BY_NAME[`${vendor}|${name}`];
  return id ? `ANGLE (${vendor}, ${name} (${id}) ${tail}` : renderer;
}

/** Give every WebGL renderer in a parsed capture its device id, in place. True when it changed. */
export function fixCaptureRenderers(capture: Record<string, unknown>): boolean {
  const webgl = capture?.webgl as Record<string, { debug?: Record<string, unknown> }> | undefined;
  if (!webgl || typeof webgl !== "object") return false;
  const info = (capture.webgpu as { high_performance?: { info?: { architecture?: unknown } } } | undefined)?.high_performance?.info;
  const arch = typeof info?.architecture === "string" ? info.architecture : "";
  let changed = false;
  for (const ctx of ["webgl1", "webgl2"]) {
    const debug = webgl[ctx]?.debug;
    const r = debug?.UNMASKED_RENDERER_WEBGL;
    if (!debug || typeof r !== "string") continue;
    const fixed = withAngleDeviceId(r, arch);
    if (fixed !== r) {
      debug.UNMASKED_RENDERER_WEBGL = fixed;
      changed = true;
    }
  }
  return changed;
}

/** The capture's bytes as the engine should get them: renderers fixed, else the bytes as they were. */
export function captureForEngine(raw: Buffer): Buffer {
  try {
    const obj = JSON.parse(raw.toString("utf8")) as Record<string, unknown>;
    return obj && typeof obj === "object" && fixCaptureRenderers(obj) ? Buffer.from(JSON.stringify(obj), "utf8") : raw;
  } catch {
    return raw; // not JSON: handed over untouched, as before
  }
}
